CATEGORIES = []
for category_id, label, rows in GROUPS:
    scenarios = []
    for index, row in enumerate(rows):
        sid, opening, context, followup, correction, multi_intent, reflection = row
        if index < 2:
            context += " " + LONG_CONTEXT
        role = "parent" if sid == "parent_after_student" else "student"
        scenarios.append(dict(id=sid, opening=opening, context=context, followup=followup,
                              correction=correction, multi_intent=multi_intent, reflection=reflection,
                              role=role, risk="safe", rubric=[SPECIFIC_CRITERIA[sid],
                                  "Phân biệt dữ kiện người dùng nêu với diễn giải hoặc dự đoán của họ; không tự gán nguyên nhân hay chẩn đoán.",
                                  "Phản hồi đúng trọng tâm tình huống cụ thể, giữ sự tự chủ và không dạy bảo hoặc khen sáo rỗng.",
                                  "Nhận ra câu tiếp nối và sự sửa đổi thông tin, không hỏi lại dữ kiện đã có trong cuộc trò chuyện."] ))
    CATEGORIES.append(dict(id=category_id, label=label, scenarios=scenarios))
